export type ArrowLine = "solid" | "dashed"
export type ArrowHead = "filled" | "open" | "cross" | "none"
export type NotePlacement = "left" | "right" | "over"

export interface SeqParticipant {
  id: string
  label: string
  /** `actor` keyword renders a person glyph instead of a plain box. */
  actor: boolean
  boxId?: string
  /** Shown in a hover tooltip on the participant's box. Set via `%% tooltip Name: text`. */
  explanation?: string
}

export interface SeqBox {
  id: string
  label: string
  participantIds: string[]
  /** Shown in a hover tooltip on the container. Set via `%% tooltip Label: text`. */
  explanation?: string
}

export interface SeqMessage {
  kind: "message"
  index: number
  from: string
  to: string
  text: string
  line: ArrowLine
  head: ArrowHead
  self: boolean
  /** `+` suffix: activate the target after this message. */
  activateTarget: boolean
  /** `-` suffix: deactivate the source after this message. */
  deactivateSource: boolean
  /** Shown in a hover tooltip on the message label, and used as a JourneyPlayer step caption. Set via trailing `%% tooltip: text`. */
  explanation?: string
  /**
   * How long (ms) this step holds before the next one animates in, overriding
   * the default stagger. Set via trailing `%% duration: <ms>` (combine with a
   * tooltip using `%% tooltip: text | duration: 2000`). Useful for giving a
   * dense or important step more time to read during JourneyPlayer playback.
   */
  durationMs?: number
}

export interface SeqNote {
  kind: "note"
  index: number
  placement: NotePlacement
  participantIds: string[]
  text: string
  /** Shown in a hover tooltip on the note, and used as a JourneyPlayer step caption. Set via trailing `%% tooltip: text`. */
  explanation?: string
  /** How long (ms) this step holds before the next one animates in. Set via trailing `%% duration: <ms>`. See `SeqMessage.durationMs`. */
  durationMs?: number
}

export interface SeqActivation {
  kind: "activate" | "deactivate"
  index: number
  participantId: string
}

export type SeqEvent = SeqMessage | SeqNote | SeqActivation

export interface SeqModel {
  title?: string
  participants: SeqParticipant[]
  boxes: SeqBox[]
  events: SeqEvent[]
}

export interface SequenceLayoutOptions {
  /** Horizontal distance between lifeline centers. */
  columnGap?: number
  /** Vertical distance between consecutive messages. */
  messageGap?: number
  /** Repeat the participant boxes at the bottom of the diagram. */
  showBottomActors?: boolean
  /**
   * Play a one-time fade+rise entrance animation on nodes, staggered
   * left-to-right by column. Off by default; used by JourneyPlayer slides.
   */
  animateIn?: boolean
  /**
   * Multiplier applied to every `animateIn` delay/duration. 1 is normal
   * pace, >1 slows the reveal down (more time to read each step), <1
   * speeds it up. Only has an effect when `animateIn` is set.
   */
  speed?: number
}

import type {
  ArrowHead,
  ArrowLine,
  SeqBox,
  SeqEvent,
  SeqModel,
  SeqParticipant,
} from "./types"

/**
 * Clean common AI-generated formatting artifacts while preserving Mermaid
 * message content. The input is never treated as HTML or executed.
 */
export function normalizeSequenceSource(input: string): string {
  let source = input.replace(/\r\n?/g, "\n").trim()
  // A single JSON-quoted string commonly comes back from older model APIs.
  if (source.startsWith('"') && source.endsWith('"')) {
    try {
      const value: unknown = JSON.parse(source)
      if (typeof value === "string") source = value
    } catch { /* Preserve original input if malformed. */ }
  }
  // Remove only the outer Mermaid/code fence, never code-like message labels.
  source = source
    .replace(/^```(?:mermaid|mmd|sequenceDiagram)?[ \t]*\n/i, "")
    .replace(/\n[ \t]*```[ \t]*$/, "")
  if (!source.includes("\n") && /\\n|\\r\\n/.test(source)) {
    source = source.replace(/\\r\\n|\\n/g, "\n")
  }
  source = source
    .replace(/<br\s*\/?\s*>/gi, "\n")
    .replace(/<\/?(?:p|div|pre|code)(?:\s+[^<>]*?)?\s*>/gi, "\n")
    .replace(/<\/?(?:span|strong|em|b|i)(?:\s+[^<>]*?)?\s*>/gi, "")
    .replace(/&(?:gt|lt|amp);/gi, (entity) =>
      ({ "&gt;": ">", "&lt;": "<", "&amp;": "&" })[entity.toLowerCase()] ?? entity)
  return source.split("\n").map((line) => line.trim()).filter(Boolean).join("\n")
}

interface ArrowSpec {
  token: string
  line: ArrowLine
  head: ArrowHead
}

// Ordered most-specific first so `-->>` wins over `->>`, `-->` over `->`, etc.
const ARROWS: ArrowSpec[] = [
  { token: "-->>", line: "dashed", head: "filled" },
  { token: "->>", line: "solid", head: "filled" },
  { token: "--x", line: "dashed", head: "cross" },
  { token: "-x", line: "solid", head: "cross" },
  { token: "--)", line: "dashed", head: "open" },
  { token: "-)", line: "solid", head: "open" },
  { token: "-->", line: "dashed", head: "none" },
  { token: "->", line: "solid", head: "none" },
]

const IGNORED_BLOCK_STARTS =
  /^(loop|alt|else|opt|par|and|critical|option|break|rect|autonumber)\b/i
const PARTICIPANT_TOOLTIP = /^tooltip\s+([^:]+):\s*(.+)$/i
const STEP_DIRECTIVE = /^(tooltip|duration)\s*:\s*(.+?)\s*$/i

function parseStepDirectives(commentBody: string): { explanation?: string; durationMs?: number } {
  const out: { explanation?: string; durationMs?: number } = {}
  for (const part of commentBody.split("|")) {
    const m = part.trim().match(STEP_DIRECTIVE)
    if (!m) continue
    const key = m[1].toLowerCase()
    if (key === "tooltip") {
      out.explanation = m[2].trim()
    } else {
      const ms = Number.parseInt(m[2], 10)
      if (Number.isFinite(ms) && ms > 0) out.durationMs = ms
    }
  }
  return out
}

function extractTooltip(
  rawLine: string,
  labelNotes: Map<string, string>,
): { line: string; explanation?: string; durationMs?: number; consumed: boolean } {
  const i = rawLine.indexOf("%%")
  if (i === -1) return { line: rawLine.trim(), consumed: false }
  const before = rawLine.slice(0, i).trim()
  const commentBody = rawLine.slice(i + 2).trim()
  const participantMatch = commentBody.match(PARTICIPANT_TOOLTIP)
  if (participantMatch) {
    labelNotes.set(participantMatch[1].trim().toLowerCase(), participantMatch[2].trim())
    if (!before) return { line: "", consumed: true }
    return { line: before, consumed: false }
  }
  const { explanation, durationMs } = parseStepDirectives(commentBody)
  if (explanation !== undefined || durationMs !== undefined) {
    return { line: before, explanation, durationMs, consumed: false }
  }
  return { line: before, consumed: false }
}

function findArrow(text: string): { spec: ArrowSpec; at: number } | null {
  let best: { spec: ArrowSpec; at: number } | null = null
  for (const spec of ARROWS) {
    const at = text.indexOf(spec.token)
    if (at === -1) continue
    if (!best || at < best.at) best = { spec, at }
  }
  return best
}

export function parseSequenceDiagram(input: string): SeqModel {
  const participants: SeqParticipant[] = []
  const byId = new Map<string, SeqParticipant>()
  const boxes: SeqBox[] = []
  const events: SeqEvent[] = []
  const labelNotes = new Map<string, string>()
  let title: string | undefined
  let currentBox: SeqBox | null = null
  let eventIndex = 0

  const ensureParticipant = (raw: string, actor = false): SeqParticipant => {
    const id = raw.trim()
    let p = byId.get(id)
    if (!p) {
      p = { id, label: id, actor }
      byId.set(id, p)
      participants.push(p)
      if (currentBox) {
        p.boxId = currentBox.id
        currentBox.participantIds.push(id)
      }
    }
    return p
  }

  const lines = normalizeSequenceSource(input).split("\n")
  for (const rawLine of lines) {
    const tip = extractTooltip(rawLine, labelNotes)
    if (tip.consumed) continue
    const line = tip.line
    const messageExplanation = tip.explanation
    const messageDurationMs = tip.durationMs
    if (!line) continue

    const lower = line.toLowerCase()
    if (lower === "sequencediagram") continue

    if (lower.startsWith("title")) {
      const m = line.match(/^title\s*:?\s*(.+)$/i)
      if (m) title = m[1].trim()
      continue
    }

    if (lower.startsWith("box ") || lower === "box") {
      const rest = line.slice(3).trim()
      const label = rest
        .replace(/^rgba?\([^)]*\)\s*/i, "")
        .replace(/^#[0-9a-f]{3,8}\s+/i, "")
        .replace(/^transparent\s+/i, "")
      currentBox = { id: `box-${boxes.length}`, label: label.trim(), participantIds: [] }
      boxes.push(currentBox)
      continue
    }

    if (lower === "end") {
      if (currentBox) currentBox = null
      continue
    }
    if (IGNORED_BLOCK_STARTS.test(line)) continue

    const partMatch = line.match(/^(participant|actor)\s+(.+)$/i)
    if (partMatch) {
      const isActor = partMatch[1].toLowerCase() === "actor"
      const body = partMatch[2].trim()
      const asMatch = body.match(/^(.+?)\s+as\s+(.+)$/i)
      if (asMatch) {
        const p = ensureParticipant(asMatch[1], isActor)
        p.label = asMatch[2].trim()
        p.actor = isActor
      } else {
        const p = ensureParticipant(body, isActor)
        p.actor = isActor
      }
      continue
    }

    const noteMatch = line.match(/^note\s+(right of|left of|over)\s+(.+?)\s*:\s*(.+)$/i)
    if (noteMatch) {
      const placement = noteMatch[1].toLowerCase().startsWith("right")
        ? "right"
        : noteMatch[1].toLowerCase().startsWith("left") ? "left" : "over"
      const ids = noteMatch[2].split(",").map((s) => s.trim()).filter(Boolean)
      ids.forEach((id) => ensureParticipant(id))
      events.push({
        kind: "note",
        index: eventIndex++,
        placement,
        participantIds: ids,
        text: noteMatch[3].trim(),
        explanation: messageExplanation,
        durationMs: messageDurationMs,
      })
      continue
    }

    const actMatch = line.match(/^(activate|deactivate)\s+(.+)$/i)
    if (actMatch) {
      const id = actMatch[2].trim()
      ensureParticipant(id)
      events.push({
        kind: actMatch[1].toLowerCase() as "activate" | "deactivate",
        index: eventIndex++,
        participantId: id,
      })
      continue
    }

    const arrow = findArrow(line)
    if (arrow) {
      const from = line.slice(0, arrow.at).trim()
      let after = line.slice(arrow.at + arrow.spec.token.length)
      let text = ""
      const colon = after.indexOf(":")
      if (colon !== -1) {
        text = after.slice(colon + 1).trim()
        after = after.slice(0, colon)
      }
      let target = after.trim()
      let activateTarget = false
      let deactivateSource = false
      if (target.startsWith("+")) {
        activateTarget = true
        target = target.slice(1).trim()
      } else if (target.startsWith("-")) {
        deactivateSource = true
        target = target.slice(1).trim()
      }
      if (!from || !target) continue
      ensureParticipant(from)
      ensureParticipant(target)
      events.push({
        kind: "message",
        index: eventIndex++,
        from,
        to: target,
        text,
        line: arrow.spec.line,
        head: arrow.spec.head,
        self: from === target,
        activateTarget,
        deactivateSource,
        explanation: messageExplanation,
        durationMs: messageDurationMs,
      })
      continue
    }
  }

  for (const p of participants) {
    const text = labelNotes.get(p.id.toLowerCase()) ?? labelNotes.get(p.label.toLowerCase())
    if (text) p.explanation = text
  }
  for (const b of boxes) {
    const text = labelNotes.get(b.label.toLowerCase())
    if (text) b.explanation = text
  }

  return { title, participants, boxes, events }
}

import { type Edge, type Node, Position } from "@xyflow/react"

import type { SeqModel, SequenceLayoutOptions } from "./types"

const ACTOR_W = 132
const ACTOR_H = 52
const MARGIN_X = 40
const MARGIN_TOP = 24
const BOX_LABEL_H = 26
const FIRST_MSG_OFFSET = 44
const SELF_H = 46
const NOTE_H = 44
const ACT_W = 10
const BOTTOM_GAP = 20

export interface HandleSpec {
  id: string
  type: "source" | "target"
  top: number
}

const BASE_ACTOR_STAGGER_MS = 70
const BASE_TRAVEL_MS = 650
// Conservative sixth-grade pace: ~160 WPM, plus a short orientation beat for
// technical fragments that are scanned differently from continuous prose.
const READING_WPM = 160
const MS_PER_WORD = 60_000 / READING_WPM
const READING_ORIENTATION_MS = 600
const MIN_STEP_HOLD_MS = 1600
const MAX_STEP_HOLD_MS = 5000
const BASE_SETTLE_PAD_MS = 150

function readableHoldMs(text: string) {
  const words = text.trim().match(/\S+/g)?.length ?? 0
  const readingTime = words * MS_PER_WORD + READING_ORIENTATION_MS
  return Math.min(MAX_STEP_HOLD_MS, Math.max(MIN_STEP_HOLD_MS, readingTime))
}

export interface StepSchedule {
  /** Delay (ms) before the actor boxes have finished settling in. */
  actorSettleDelay: number
  /** Absolute entrance delay for each message/note in chronological order. */
  delays: number[]
}

/**
 * Actors settle first, then messages/notes reveal one at a time. Default holds
 * scale with visible text at a sixth-grade reading pace; explicit
 * `%% duration: <ms>` annotations remain authoritative.
 */
export function getStepSchedule(model: SeqModel, speed = 1): StepSchedule {
  const actorSettleDelay =
    model.participants.length * BASE_ACTOR_STAGGER_MS * speed + BASE_SETTLE_PAD_MS * speed
  const delays: number[] = []
  let cursor = actorSettleDelay
  for (const ev of model.events) {
    if (ev.kind !== "message" && ev.kind !== "note") continue
    delays.push(cursor)
    const defaultHold = readableHoldMs(ev.text)
    const hold = ev.durationMs != null ? ev.durationMs * speed : defaultHold * speed
    cursor += hold
  }
  return { actorSettleDelay, delays }
}

export interface SequenceGraph {
  nodes: Node[]
  edges: Edge[]
  width: number
  height: number
}

/** Convert a parsed model into positioned React Flow nodes and edges. */
export function buildSequenceGraph(
  model: SeqModel,
  options: SequenceLayoutOptions = {},
): SequenceGraph {
  const COL_GAP = options.columnGap ?? 220
  const MSG_GAP = options.messageGap ?? 56
  const showBottom = options.showBottomActors ?? true
  const animateIn = options.animateIn ?? false
  const speed = options.speed ?? 1
  const STAGGER_MS = BASE_ACTOR_STAGGER_MS * speed

  const index = new Map<string, number>()
  model.participants.forEach((p, i) => index.set(p.id, i))
  const xOf = (id: string) =>
    MARGIN_X + ACTOR_W / 2 + (index.get(id) ?? 0) * COL_GAP
  const enterDelayOf = (id: string) => (index.get(id) ?? 0) * STAGGER_MS

  const { delays: stepDelays } = getStepSchedule(model, speed)
  let stepIndex = 0
  const nextStepDelay = () => stepDelays[stepIndex++]

  const hasBoxes = model.boxes.length > 0
  const headY = MARGIN_TOP + (hasBoxes ? BOX_LABEL_H : 0)
  const lifelineTop = headY + ACTOR_H

  const handles: Record<string, HandleSpec[]> = {}
  const addHandle = (
    pid: string,
    id: string,
    type: "source" | "target",
    absY: number,
  ) => {
    ;(handles[pid] ||= []).push({ id, type, top: absY - lifelineTop })
  }

  interface MsgLayout {
    index: number
    from: string
    to: string
    self: boolean
    data: Record<string, unknown>
  }
  const msgLayouts: MsgLayout[] = []

  interface ActBar {
    pid: string
    top: number
    height: number
    depth: number
  }
  const activations: ActBar[] = []
  const activeStacks: Record<string, { startY: number; depth: number }[]> = {}
  const pushAct = (pid: string, startY: number) => {
    const stack = (activeStacks[pid] ||= [])
    stack.push({ startY, depth: stack.length })
  }
  const popAct = (pid: string, endY: number) => {
    const stack = activeStacks[pid]
    if (!stack || stack.length === 0) return
    const s = stack.pop()!
    activations.push({
      pid,
      top: s.startY,
      height: Math.max(endY - s.startY, 18),
      depth: s.depth,
    })
  }

  interface NoteLayout {
    id: string
    x: number
    y: number
    width: number
    text: string
    explanation?: string
    enterDelay: number
  }
  const notes: NoteLayout[] = []

  let y = lifelineTop + FIRST_MSG_OFFSET

  for (const ev of model.events) {
    if (ev.kind === "message") {
      const my = y
      if (ev.self) {
        const y2 = my + SELF_H
        addHandle(ev.from, `m${ev.index}-s`, "source", my)
        addHandle(ev.from, `m${ev.index}-t`, "target", y2)
        y = y2 + MSG_GAP
      } else {
        addHandle(ev.from, `m${ev.index}-s`, "source", my)
        addHandle(ev.to, `m${ev.index}-t`, "target", my)
        y = my + MSG_GAP
      }
      if (ev.activateTarget) pushAct(ev.to, my)
      if (ev.deactivateSource) popAct(ev.from, ev.self ? my + SELF_H : my)
      msgLayouts.push({
        index: ev.index,
        from: ev.from,
        to: ev.to,
        self: ev.self,
        data: {
          index: ev.index,
          text: ev.text,
          line: ev.line,
          head: ev.head,
          self: ev.self,
          from: ev.from,
          to: ev.to,
          explanation: ev.explanation,
          animateIn,
          enterDelay: nextStepDelay(),
          travelMs: BASE_TRAVEL_MS * speed,
        },
      })
    } else if (ev.kind === "note") {
      const ids = ev.participantIds
      let nx: number
      let nw: number
      if (ev.placement === "over") {
        const xs = ids.map(xOf)
        const min = Math.min(...xs)
        const max = Math.max(...xs)
        nw = ids.length > 1 ? max - min + ACTOR_W : 150
        nx = (min + max) / 2 - nw / 2
      } else if (ev.placement === "right") {
        nx = xOf(ids[0]) + 16
        nw = 150
      } else {
        nw = 150
        nx = xOf(ids[0]) - 16 - nw
      }
      notes.push({
        id: `note-${ev.index}`,
        x: nx,
        y,
        width: nw,
        text: ev.text,
        explanation: ev.explanation,
        enterDelay: nextStepDelay(),
      })
      y += NOTE_H + 20
    } else if (ev.kind === "activate") {
      pushAct(ev.participantId, y)
    } else if (ev.kind === "deactivate") {
      popAct(ev.participantId, y)
    }
  }

  for (const pid of Object.keys(activeStacks)) {
    while (activeStacks[pid].length) popAct(pid, y)
  }

  const bottomHeadY = y + BOTTOM_GAP
  const lifelineHeight = (showBottom ? bottomHeadY : y + BOTTOM_GAP) - lifelineTop
  const height = (showBottom ? bottomHeadY + ACTOR_H : y + BOTTOM_GAP) + MARGIN_TOP
  const lastX = xOf(model.participants[model.participants.length - 1]?.id ?? "")
  const width = lastX + ACTOR_W / 2 + MARGIN_X

  const nodes: Node[] = []

  for (const box of model.boxes) {
    if (box.participantIds.length === 0) continue
    const xs = box.participantIds.map(xOf)
    const left = Math.min(...xs) - ACTOR_W / 2 - 14
    const right = Math.max(...xs) + ACTOR_W / 2 + 14
    nodes.push({
      id: box.id,
      type: "seqGroup",
      position: { x: left, y: MARGIN_TOP },
      data: {
        boxId: box.id,
        label: box.label,
        width: right - left,
        height: height - MARGIN_TOP * 1.5,
        explanation: box.explanation,
        animateIn,
        enterDelay: Math.min(...box.participantIds.map(enterDelayOf)),
      },
      draggable: false,
      selectable: false,
      zIndex: 0,
    })
  }

  for (const p of model.participants) {
    nodes.push({
      id: `ll-${p.id}`,
      type: "seqLifeline",
      position: { x: xOf(p.id) - 1, y: lifelineTop },
      data: { participant: p.id, height: lifelineHeight, handles: handles[p.id] ?? [] },
      draggable: false,
      selectable: false,
      zIndex: 1,
    })
  }

  activations.forEach((a, i) => {
    nodes.push({
      id: `act-${i}`,
      type: "seqActivation",
      position: { x: xOf(a.pid) - ACT_W / 2 + a.depth * 4, y: a.top },
      data: { participant: a.pid, height: a.height },
      draggable: false,
      selectable: false,
      zIndex: 3,
    })
  })

  for (const p of model.participants) {
    nodes.push({
      id: `head-${p.id}`,
      type: "seqActor",
      position: { x: xOf(p.id) - ACTOR_W / 2, y: headY },
      data: {
        participant: p.id,
        label: p.label,
        actor: p.actor,
        width: ACTOR_W,
        explanation: p.explanation,
        placement: "top",
        animateIn,
        enterDelay: enterDelayOf(p.id),
      },
      draggable: false,
      selectable: false,
      zIndex: 5,
    })
    if (showBottom) {
      nodes.push({
        id: `head-b-${p.id}`,
        type: "seqActor",
        position: { x: xOf(p.id) - ACTOR_W / 2, y: bottomHeadY },
        data: {
          participant: p.id,
          label: p.label,
          actor: p.actor,
          width: ACTOR_W,
          explanation: p.explanation,
          placement: "bottom",
          animateIn,
          enterDelay: enterDelayOf(p.id),
        },
        draggable: false,
        selectable: false,
        zIndex: 5,
      })
    }
  }

  for (const n of notes) {
    nodes.push({
      id: n.id,
      type: "seqNote",
      position: { x: n.x, y: n.y },
      data: {
        text: n.text,
        width: n.width,
        height: NOTE_H,
        explanation: n.explanation,
        animateIn,
        enterDelay: n.enterDelay,
      },
      draggable: false,
      selectable: false,
      zIndex: 6,
    })
  }

  const edges: Edge[] = msgLayouts.map((m) => ({
    id: `e${m.index}`,
    source: `ll-${m.from}`,
    sourceHandle: `m${m.index}-s`,
    target: `ll-${m.to}`,
    targetHandle: `m${m.index}-t`,
    type: "seqMessage",
    data: m.data,
    zIndex: 4,
  }))

  return { nodes, edges, width, height }
}

export { Position }

"use client"

import { createContext, useContext } from "react"

export interface SequenceHoverState {
  selectedMessageIndex: number | null
  onMessageSelect: (event: { index: number; from: string; to: string; text: string }) => void
  hoveredEdge: string | null
  /** Participant hovered directly (its own box), independent of any edge. */
  hoveredParticipant: string | null
  /** `box` container (tier grouping) currently hovered, independent of any edge. */
  hoveredBox: string | null
  activeParticipants: Set<string>
  setHover: (edge: string | null, participants: string[]) => void
  setParticipantHover: (participant: string | null) => void
  setBoxHover: (boxId: string | null) => void
}

export const SequenceHoverContext = createContext<SequenceHoverState>({
  selectedMessageIndex: null,
  onMessageSelect: () => {},
  hoveredEdge: null,
  hoveredParticipant: null,
  hoveredBox: null,
  activeParticipants: new Set(),
  setHover: () => {},
  setParticipantHover: () => {},
  setBoxHover: () => {},
})

export function useSequenceHover() {
  return useContext(SequenceHoverContext)
}

"use client"

import { useState } from "react"

import { Handle, type NodeProps, Position } from "@xyflow/react"
import { User } from "lucide-react"

import { cn } from "@/lib/utils"

import { useSequenceHover } from "./context"
import type { HandleSpec } from "./layout"
import { SeqTooltip } from "./tooltip"

/** Grouping box drawn behind a set of participants. Hover reveals its explanation, if any. */
export function SeqGroupNode({ data }: NodeProps) {
  const d = data as {
    boxId: string
    label: string
    width: number
    height: number
    explanation?: string
    animateIn?: boolean
    enterDelay?: number
  }
  const { hoveredBox, setBoxHover } = useSequenceHover()
  const hovered = hoveredBox === d.boxId

  return (
    <div
      role={d.explanation ? "button" : undefined}
      tabIndex={d.explanation ? 0 : undefined}
      className={cn(
        "relative cursor-default border bg-seq-group/[0.06] transition-colors",
        hovered
          ? "border-solid border-seq-accent bg-seq-accent/[0.08] ring-1 ring-seq-accent"
          : "border-dashed border-border",
        d.animateIn ? "seq-enter" : undefined,
      )}
      style={{
        width: d.width,
        height: d.height,
        animationDelay: d.animateIn ? `${d.enterDelay ?? 0}ms` : undefined,
      }}
      onMouseEnter={() => setBoxHover(d.boxId)}
      onMouseLeave={() => setBoxHover(null)}
      onFocus={() => setBoxHover(d.boxId)}
      onBlur={() => setBoxHover(null)}
    >
      {d.label ? (
        <SeqTooltip text={d.explanation} visible={hovered} placement="top">
          <span
            className={cn(
              "absolute left-3 -top-3 border bg-card px-2 py-0.5 text-xs font-medium tracking-wide transition-colors",
              hovered ? "border-seq-accent text-seq-accent" : "border-border text-muted-foreground",
            )}
          >
            {d.label}
          </span>
        </SeqTooltip>
      ) : null}
    </div>
  )
}

/** Vertical dashed lifeline that hosts message handles. */
export function SeqLifelineNode({ data }: NodeProps) {
  const d = data as { participant: string; height: number; handles: HandleSpec[] }
  const { activeParticipants, hoveredEdge } = useSequenceHover()
  const active = activeParticipants.has(d.participant)
  return (
    <div style={{ width: 2, height: d.height }} className="relative">
      <div
        className={cn(
          "absolute left-1/2 top-0 h-full -translate-x-1/2 border-l border-dashed transition-colors",
          active ? "border-seq-accent" : "border-seq-lifeline/70",
        )}
        style={{ opacity: hoveredEdge && !active ? 0.4 : 1 }}
      />
      {d.handles.map((h) => (
        <Handle
          key={h.id}
          id={h.id}
          type={h.type}
          position={Position.Left}
          isConnectable={false}
          style={{
            top: h.top,
            left: 1,
            width: 1,
            height: 1,
            minWidth: 0,
            minHeight: 0,
            border: "none",
            background: "transparent",
            opacity: 0,
          }}
        />
      ))}
    </div>
  )
}

/** Activation bar overlaid on a lifeline. */
export function SeqActivationNode({ data }: NodeProps) {
  const d = data as { participant: string; height: number }
  const { activeParticipants, hoveredEdge } = useSequenceHover()
  const active = activeParticipants.has(d.participant)
  return (
    <div
      className={cn(
        "border transition-colors",
        active
          ? "border-seq-accent bg-seq-accent/25"
          : "border-seq-accent/40 bg-seq-activation",
      )}
      style={{ width: 10, height: d.height, opacity: hoveredEdge && !active ? 0.5 : 1 }}
    />
  )
}

/** Participant head box (or actor glyph). Hover reveals its explanation, if any. */
export function SeqActorNode({ data }: NodeProps) {
  const d = data as {
    participant: string
    label: string
    actor: boolean
    width: number
    explanation?: string
    placement?: "top" | "bottom"
    animateIn?: boolean
    enterDelay?: number
  }
  const { activeParticipants, hoveredEdge, hoveredParticipant, setParticipantHover } =
    useSequenceHover()
  const active = activeParticipants.has(d.participant)
  const directHover = hoveredParticipant === d.participant
  const highlighted = active || directHover
  // The same participant renders a top and (optionally) a bottom actor box that
  // share hover state. Only the top box owns the tooltip, so hovering either one
  // doesn't pop the explanation twice.
  const isBottom = d.placement === "bottom"
  const tooltipText = isBottom ? undefined : d.explanation

  return (
    <SeqTooltip text={tooltipText} visible={directHover} placement="top">
      <div
        role={tooltipText ? "button" : undefined}
        tabIndex={tooltipText ? 0 : undefined}
        className={cn(
          "flex h-[52px] cursor-default items-center justify-center gap-2 border bg-card px-3 text-center transition-colors",
          highlighted ? "border-seq-accent ring-1 ring-seq-accent" : "border-border",
          d.animateIn ? "seq-enter" : undefined,
        )}
        style={{
          width: d.width,
          opacity: hoveredEdge && !active ? 0.45 : 1,
          animationDelay: d.animateIn ? `${d.enterDelay ?? 0}ms` : undefined,
        }}
        onMouseEnter={() => setParticipantHover(d.participant)}
        onMouseLeave={() => setParticipantHover(null)}
        onFocus={() => setParticipantHover(d.participant)}
        onBlur={() => setParticipantHover(null)}
      >
        {d.actor ? (
          <User className="size-4 shrink-0 text-muted-foreground" aria-hidden />
        ) : null}
        <span className="text-sm font-medium leading-tight text-card-foreground text-balance">
          {d.label}
        </span>
      </div>
    </SeqTooltip>
  )
}

/** Note / badge callout. Hover reveals its explanation, if any. */
export function SeqNoteNode({ data }: NodeProps) {
  const d = data as {
    text: string
    width: number
    height: number
    explanation?: string
    animateIn?: boolean
    enterDelay?: number
  }
  const [hovered, setHovered] = useState(false)

  return (
    <SeqTooltip text={d.explanation} visible={hovered}>
      <div
        role={d.explanation ? "button" : undefined}
        tabIndex={d.explanation ? 0 : undefined}
        className={cn(
          "flex cursor-default items-center justify-center border border-border bg-muted px-3 py-2 text-center text-xs leading-snug text-muted-foreground transition-colors",
          d.explanation && hovered ? "border-seq-accent text-foreground" : undefined,
          d.animateIn ? "seq-enter" : undefined,
        )}
        style={{
          width: d.width,
          minHeight: d.height,
          animationDelay: d.animateIn ? `${d.enterDelay ?? 0}ms` : undefined,
        }}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        onFocus={() => setHovered(true)}
        onBlur={() => setHovered(false)}
      >
        {d.text}
      </div>
    </SeqTooltip>
  )
}

export const sequenceNodeTypes = {
  seqGroup: SeqGroupNode,
  seqLifeline: SeqLifelineNode,
  seqActivation: SeqActivationNode,
  seqActor: SeqActorNode,
  seqNote: SeqNoteNode,
}

"use client"

import { useEffect, useRef } from "react"
import { BaseEdge, EdgeLabelRenderer, type EdgeProps } from "@xyflow/react"

import { cn } from "@/lib/utils"

import { useSequenceHover } from "./context"
import { SeqTooltip } from "./tooltip"
import type { ArrowHead, ArrowLine } from "./types"

const MARKER: Record<ArrowHead, string> = {
  filled: "url(#seq-arrow)",
  open: "url(#seq-arrow-open)",
  cross: "url(#seq-cross)",
  none: "",
}

interface MessageData {
  index: number
  text: string
  line: ArrowLine
  head: ArrowHead
  self: boolean
  from: string
  to: string
  explanation?: string
  animateIn?: boolean
  enterDelay?: number
  /** Duration (ms) for the traveling dot to fly from source to target. */
  travelMs?: number
}

export function SeqMessageEdge({
  id,
  sourceX,
  sourceY,
  targetX,
  targetY,
  data,
}: EdgeProps) {
  const d = data as unknown as MessageData
  const { hoveredEdge, setHover, selectedMessageIndex, onMessageSelect } = useSequenceHover()
  const hovered = hoveredEdge === id || selectedMessageIndex === d.index
  const dimmed = hoveredEdge !== null && !hovered

  let path: string
  let labelX: number
  let labelY: number

  if (d.self) {
    const loop = 62
    const x = sourceX
    path = `M ${x} ${sourceY} C ${x + loop} ${sourceY}, ${x + loop} ${targetY}, ${x} ${targetY}`
    labelX = x + loop
    labelY = (sourceY + targetY) / 2
  } else {
    path = `M ${sourceX} ${sourceY} L ${targetX} ${targetY}`
    labelX = (sourceX + targetX) / 2
    labelY = sourceY
  }

  const onEnter = () => setHover(id, [d.from, d.to])
  const onLeave = () => setHover(null, [])
  const select = () => onMessageSelect({ index: d.index, from: d.from, to: d.to, text: d.text })
  const enterDelay = d.animateIn ? `${d.enterDelay ?? 0}ms` : undefined
  const travelMs = d.travelMs ?? 360
  // The label reveals once the traveling dot lands, so it reads as the
  // message "arriving" rather than appearing alongside the line's own pop-in.
  const labelDelay = d.animateIn ? `${(d.enterDelay ?? 0) + travelMs}ms` : undefined

  const motionRef = useRef<SVGAnimateMotionElement>(null)
  useEffect(() => {
    if (!d.animateIn || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return
    const timer = window.setTimeout(() => motionRef.current?.beginElement(), d.enterDelay ?? 0)
    return () => window.clearTimeout(timer)
  }, [d.animateIn, d.enterDelay, path])

  return (
    <>
      <BaseEdge
        id={id}
        path={path}
        markerEnd={MARKER[d.head]}
        interactionWidth={22}
        className={d.animateIn ? "seq-edge-pop" : undefined}
        style={{
          stroke: "var(--seq-accent)",
          strokeWidth: hovered ? 2.5 : 1.5,
          strokeDasharray: d.line === "dashed" ? "6 4" : undefined,
          opacity: dimmed ? 0.35 : 1,
          transition: "opacity 120ms, stroke-width 120ms",
          animationDelay: enterDelay,
        }}
      />
      {d.animateIn ? (
        // Traveling "packet" that flies from source to target along the
        // message's own path the instant it appears — reads as motion
        // in-flight rather than a plain (and, per feedback, sluggish-feeling)
        // fade. Its arrival is what visually completes the edge.
        <circle
          className="seq-edge-dot"
          r={4}
          fill="var(--seq-accent)"
          style={{
            animationDuration: `${travelMs}ms`,
            animationDelay: enterDelay,
            pointerEvents: "none",
          }}
        >
          <animateMotion
            ref={motionRef}
            path={path}
            dur={`${travelMs}ms`}
            begin="indefinite"
            fill="freeze"
          />
        </circle>
      ) : null}
      <EdgeLabelRenderer>
        {d.text ? (
          <div
            className={cn(
              "nodrag nopan pointer-events-auto absolute -translate-x-1/2 -translate-y-1/2",
              d.animateIn ? "seq-enter" : undefined,
            )}
            style={{
              left: labelX,
              top: labelY,
              opacity: dimmed ? 0.4 : 1,
              animationDelay: labelDelay,
            }}
            onMouseEnter={onEnter}
            onMouseLeave={onLeave}
            onClick={select}
          >
            <SeqTooltip text={d.explanation} visible={hovered}>
              <div
                className={cn(
                  "cursor-default border px-2 py-0.5 text-xs font-medium transition-all",
                  "border-border bg-background text-foreground",
                  hovered && "ring-2 ring-seq-accent/40",
                )}
              >
                {d.text}
              </div>
            </SeqTooltip>
          </div>
        ) : null}
        {/* Invisible hit target over the line for hover when there is no label. */}
        <div
          className="nodrag nopan pointer-events-none absolute"
          style={{ left: labelX, top: labelY }}
        />
      </EdgeLabelRenderer>
      {/* Transparent wide path to capture hover along the whole line. */}
      <path
        d={path}
        className="seq-hit-target"
        fill="none"
        stroke="transparent"
        strokeWidth={22}
        style={{ pointerEvents: "stroke", cursor: "default" }}
        onMouseEnter={onEnter}
        onMouseLeave={onLeave}
        onClick={select}
      />
    </>
  )
}

export const sequenceEdgeTypes = {
  seqMessage: SeqMessageEdge,
}

import type { ReactNode } from "react"

import { cn } from "@/lib/utils"

interface SeqTooltipProps {
  /** Explanation text. When empty, no tooltip markup is rendered at all. */
  text?: string
  visible: boolean
  placement?: "top" | "bottom"
  children: ReactNode
  className?: string
}

/**
 * Small, non-portaled explanation tooltip shared by participant boxes and
 * message labels. Purely presentational — callers own the hover state so it
 * stays in sync with each element's own outline/highlight behavior.
 */
export function SeqTooltip({
  text,
  visible,
  placement = "top",
  children,
  className,
}: SeqTooltipProps) {
  return (
    <div className={cn("relative", className)}>
      {children}
      {text ? (
        <div
          role="tooltip"
          className={cn(
            "pointer-events-none absolute left-1/2 z-50 w-max max-w-[220px] -translate-x-1/2 border border-border bg-popover px-2.5 py-1.5 text-[11px] leading-snug text-popover-foreground shadow-md transition-opacity duration-150",
            placement === "top" ? "bottom-full mb-2" : "top-full mt-2",
            visible ? "opacity-100" : "opacity-0",
          )}
        >
          {text}
        </div>
      ) : null}
    </div>
  )
}

/**
 * React Flow renders `.react-flow__edges` (the SVG edge paths) and
 * `.react-flow__edgelabel-renderer` (the portal used by EdgeLabelRenderer)
 * as unstyled siblings inside the viewport. Neither sets an explicit
 * z-index, so with `z-index: auto` browsers stack them by DOM order —
 * which places edge paths above edge labels and cuts message lines
 * straight through the label text. Giving the label-renderer layer an
 * explicit z-index lifts it above the (auto = level 0) edges layer,
 * regardless of DOM order, while staying below nodes/controls.
 */
.react-flow__edgelabel-renderer {
  z-index: 1000;
}

/**
 * Journey-slide entrance: fade in with a slight rise, staggered per node via
 * an inline `animation-delay` (see layout.ts `enterDelayOf`). Opt-in only —
 * applied via the `seq-enter` class when `animateIn` is set.
 */
@keyframes seq-enter {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.seq-enter {
  animation: seq-enter 320ms ease-out both;
}

/**
 * Message edge entrance, in two parts, timed to each message's chronological
 * `enterDelay` (see layout.ts `nextStepDelay`) so messages appear one at a
 * time like a step-through playback rather than all at once:
 *
 * 1. `seq-edge-pop` snaps the line/label to fully visible the instant the
 *    message's turn arrives — no fade, so it never reads as sluggish.
 * 2. `seq-edge-dot` flies a small circular "packet" along that same path
 *    (via native SVG animateMotion using the same path geometry) from source to target, arriving right as the line pops in.
 *    This is the primary motion cue — it makes the arrival feel immediate
 *    rather than the previous plain opacity fade.
 */
@keyframes seq-edge-pop {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.seq-edge-pop {
  animation: seq-edge-pop 1ms both;
}

@keyframes seq-edge-travel {
  0% {
    opacity: 0;
  }
  12% { opacity: 1; }
  80% {
    opacity: 1;
  }
  100% {
    opacity: 0;
  }
}

.seq-edge-dot {
  animation-name: seq-edge-travel;
  animation-timing-function: linear;
  animation-fill-mode: both;
}

/**
 * JourneyPlayer mobile layout.
 *
 * The player header already allows its outer row to wrap, but the control
 * cluster inside it is intentionally a single horizontal flex row on desktop.
 * On narrow screens that row can exceed the viewport and force the entire
 * walkthrough wider than the page. Keep the desktop layout untouched and let
 * the control groups wrap into compact rows below the slide title on mobile.
 */
@media (max-width: 640px) {
  [aria-roledescription="carousel"] {
    min-width: 0;
    width: 100%;
    max-width: 100%;
    overflow: hidden;
  }

  [aria-roledescription="carousel"] > div:first-child {
    align-items: stretch;
  }

  [aria-roledescription="carousel"] > div:first-child > div:first-child {
    width: 100%;
    min-width: 0;
  }

  [aria-roledescription="carousel"] > div:first-child > div:last-child {
    display: flex;
    width: 100%;
    min-width: 0;
    flex-wrap: wrap;
    align-items: center;
    justify-content: flex-start;
    gap: 0.5rem;
  }

  [aria-roledescription="carousel"] > div:first-child > div:last-child > div {
    max-width: 100%;
    flex-shrink: 0;
  }

  /* Put slide dots on their own lightweight row and let the actual controls
     wrap naturally underneath instead of squeezing into one line. */
  [aria-roledescription="carousel"] > div:first-child > div:last-child > div:first-child {
    flex-basis: 100%;
  }

  /* Keep the diagram/code viewport bounded by the phone rather than the
     desktop-oriented fixed 420px height. Inline height is overridden only on
     mobile so the public `height` prop still behaves exactly as before on
     larger screens. */
  [aria-roledescription="carousel"] > div:nth-child(2) {
    width: 100%;
    min-width: 0;
    height: clamp(300px, 56vh, 380px) !important;
  }

  [aria-roledescription="carousel"] pre {
    min-width: 0;
    max-width: 100%;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  [aria-roledescription="carousel"] pre code {
    display: block;
    width: max-content;
    min-width: 100%;
  }

  /* Keep the live message caption and slide commentary inside the viewport
     even when they contain long URLs, identifiers, or code-like tokens. */
  [aria-roledescription="carousel"] p,
  [aria-roledescription="carousel"] span {
    overflow-wrap: anywhere;
  }
}

@media (prefers-reduced-motion: reduce) {
  .seq-enter,
  .seq-edge-pop {
    animation-duration: 1ms;
    animation-delay: 0ms !important;
  }
  .seq-edge-dot {
    animation: none;
    opacity: 0;
  }
}

/* Ensure host-wide React Flow selectors cannot paint transparent interaction edges. */
.sequence-flow-diagram .react-flow__edge .seq-hit-target { stroke: transparent !important; fill: none !important; }
.sequence-flow-diagram .react-flow__edge .seq-edge-dot { stroke: none !important; }
.sequence-flow-diagram .react-flow__edge .react-flow__edge-path { stroke: var(--seq-accent) !important; stroke-width: 1.5px; }

"use client"

import "@xyflow/react/dist/base.css"
import "./sequence-diagram.css"

import { forwardRef, useEffect, useImperativeHandle, useMemo, useRef, useState } from "react"
import {
  Background,
  BackgroundVariant,
  Controls,
  getNodesBounds,
  getViewportForBounds,
  ReactFlow,
  ReactFlowProvider,
  useReactFlow,
} from "@xyflow/react"
import { toPng } from "html-to-image"

import { cn } from "@/lib/utils"

import { SequenceHoverContext } from "./context"
import { sequenceEdgeTypes } from "./edges"
import { buildSequenceGraph } from "./layout"
import { sequenceNodeTypes } from "./nodes"
import { parseSequenceDiagram } from "./parser"
import type { SequenceLayoutOptions } from "./types"

export interface SequenceDiagramProps extends SequenceLayoutOptions {
  selectedMessageIndex?: number | null
  onMessageSelect?: (event: { index: number; from: string; to: string; text: string }) => void
  /** Mermaid-flavored sequence diagram definition. */
  chart: string
  className?: string
  /** Show the pan/zoom control bar. Defaults to true. */
  controls?: boolean
  /** Show the dotted background grid. Defaults to true. */
  background?: boolean
  /** Fit the diagram to the viewport on mount. Defaults to true. */
  fitView?: boolean
}

/** Imperative handle exposed via ref for exporting the rendered diagram. */
export interface SequenceDiagramHandle {
  /** Renders the full diagram (not just the visible viewport) to a PNG and downloads it. */
  exportPng: (fileName?: string) => Promise<void>
}

function MarkerDefs() {
  return (
    <svg width="0" height="0" className="absolute" aria-hidden focusable="false">
      <defs>
        <marker
          id="seq-arrow"
          markerWidth="12"
          markerHeight="12"
          refX="8"
          refY="4"
          orient="auto"
          markerUnits="userSpaceOnUse"
        >
          <path d="M0,0 L9,4 L0,8 z" fill="var(--seq-accent)" />
        </marker>
        <marker
          id="seq-arrow-open"
          markerWidth="12"
          markerHeight="12"
          refX="8"
          refY="4"
          orient="auto"
          markerUnits="userSpaceOnUse"
        >
          <path
            d="M0,0 L9,4 L0,8"
            fill="none"
            stroke="var(--seq-accent)"
            strokeWidth="1.5"
          />
        </marker>
        <marker
          id="seq-cross"
          markerWidth="12"
          markerHeight="12"
          refX="6"
          refY="4"
          orient="auto"
          markerUnits="userSpaceOnUse"
        >
          <path
            d="M1,1 L7,7 M7,1 L1,7"
            fill="none"
            stroke="var(--seq-accent)"
            strokeWidth="1.6"
          />
        </marker>
      </defs>
    </svg>
  )
}

const SequenceDiagramInner = forwardRef<SequenceDiagramHandle, SequenceDiagramProps>(
  function SequenceDiagramInner(
    {
      chart,
      className,
      selectedMessageIndex = null,
      onMessageSelect,
      controls = true,
      background = true,
      fitView = true,
      columnGap,
      messageGap,
      showBottomActors,
      animateIn,
      speed,
    },
    ref,
  ) {
  const containerRef = useRef<HTMLDivElement>(null)
  const { getNodes, fitView: fitDiagramToBounds } = useReactFlow()
  const [hoveredEdge, setHoveredEdge] = useState<string | null>(null)
  const [hoveredParticipant, setHoveredParticipant] = useState<string | null>(null)
  const [hoveredBox, setHoveredBox] = useState<string | null>(null)
  const [activeParticipants, setActiveParticipants] = useState<Set<string>>(
    () => new Set(),
  )

  const { nodes, edges } = useMemo(() => {
    const model = parseSequenceDiagram(chart)
    return buildSequenceGraph(model, {
      columnGap,
      messageGap,
      showBottomActors,
      animateIn,
      speed,
    })
  }, [chart, columnGap, messageGap, showBottomActors, animateIn, speed])

  useImperativeHandle(
    ref,
    () => ({
      exportPng: async (fileName = "sequence-diagram.png") => {
        const container = containerRef.current
        const currentNodes = getNodes()
        if (!container || currentNodes.length === 0) return

        const viewportEl = container.querySelector<HTMLElement>(
          ".react-flow__viewport",
        )
        if (!viewportEl) return

        const padding = 48
        const bounds = getNodesBounds(currentNodes)
        const imageWidth = Math.ceil(bounds.width + padding * 2)
        const imageHeight = Math.ceil(bounds.height + padding * 2)
        const viewport = getViewportForBounds(
          bounds,
          imageWidth,
          imageHeight,
          0.1,
          2,
          padding,
        )
        const backgroundColor = getComputedStyle(container).backgroundColor

        const dataUrl = await toPng(viewportEl, {
          backgroundColor,
          width: imageWidth,
          height: imageHeight,
          pixelRatio: 2,
          style: {
            width: `${imageWidth}px`,
            height: `${imageHeight}px`,
            transform: `translate(${viewport.x}px, ${viewport.y}px) scale(${viewport.zoom})`,
          },
        })

        const link = document.createElement("a")
        link.download = fileName
        link.href = dataUrl
        link.click()
      },
    }),
    [getNodes],
  )

  // React Flow's initial fitView can fire before the parent has its final
  // dimensions. Refit on diagram content and container resize so arrows,
  // labels and actor boxes remain fully visible on mobile, tab switches,
  // and animated journeys.
  useEffect(() => {
    if (!fitView) return
    const container = containerRef.current
    if (!container || typeof ResizeObserver === "undefined") return
    let frame = 0
    const refit = () => {
      cancelAnimationFrame(frame)
      frame = requestAnimationFrame(() => {
        if (container.clientWidth > 0 && container.clientHeight > 0) {
          void fitDiagramToBounds({ padding: 0.22, maxZoom: 1, duration: 0 })
        }
      })
    }
    const observer = new ResizeObserver(refit)
    observer.observe(container)
    refit()
    return () => {
      observer.disconnect()
      cancelAnimationFrame(frame)
    }
  }, [fitView, fitDiagramToBounds, nodes, edges])

  const hoverValue = useMemo(
    () => ({
      hoveredEdge,
      selectedMessageIndex,
      onMessageSelect: onMessageSelect ?? (() => {}),
      hoveredParticipant,
      hoveredBox,
      activeParticipants,
      setHover: (edge: string | null, participants: string[]) => {
        setHoveredEdge(edge)
        setActiveParticipants(new Set(participants))
      },
      setParticipantHover: setHoveredParticipant,
      setBoxHover: setHoveredBox,
    }),
    [hoveredEdge, hoveredParticipant, hoveredBox, activeParticipants, selectedMessageIndex, onMessageSelect],
  )

  return (
    <SequenceHoverContext.Provider value={hoverValue}>
      <div ref={containerRef} className={cn("sequence-flow-diagram relative size-full bg-background", className)}>
        <MarkerDefs />
        <ReactFlow
          nodes={nodes}
          edges={edges}
          nodeTypes={sequenceNodeTypes}
          edgeTypes={sequenceEdgeTypes}
          fitView={fitView}
          fitViewOptions={{ padding: 0.22, maxZoom: 1 }}
          minZoom={0.06}
          maxZoom={2}
          proOptions={{ hideAttribution: false }}
          nodesDraggable={false}
          nodesConnectable={false}
          elementsSelectable={false}
          edgesFocusable={false}
          panOnScroll
          zoomOnScroll={false}
          className="bg-background"
          // React Flow only enables pointer-events on a node's DOM wrapper when the
          // node is selectable/draggable or a top-level onNode* handler is set. Since
          // our nodes are neither, a harmless no-op handler here restores real hover
          // (mouseenter/mouseleave) on every custom node — group boxes, actors, etc.
          onNodeMouseEnter={() => {}}
        >
          {background ? (
            <Background
              variant={BackgroundVariant.Dots}
              gap={20}
              size={1}
              className="text-border"
            />
          ) : null}
          {controls ? <Controls showInteractive={false} /> : null}
        </ReactFlow>
      </div>
    </SequenceHoverContext.Provider>
  )
  },
)

/**
 * A lightweight, read-only sequence diagram rendered with React Flow.
 * Author diagrams with Mermaid sequence-diagram syntax. Pass a ref to access
 * imperative export methods (e.g. `ref.current.exportPng()`).
 */
export const SequenceDiagram = forwardRef<SequenceDiagramHandle, SequenceDiagramProps>(
  function SequenceDiagram(props, ref) {
    return (
      <ReactFlowProvider>
        <SequenceDiagramInner {...props} ref={ref} />
      </ReactFlowProvider>
    )
  },
)

"use client"

import { useEffect, useMemo, useState } from "react"
import {
  Check,
  ChevronLeft,
  ChevronRight,
  Copy,
  Pause,
  Play,
  Repeat2,
} from "lucide-react"

import { cn } from "@/lib/utils"

import { buildSequenceGraph, getStepSchedule } from "./layout"
import { parseSequenceDiagram } from "./parser"
import { SequenceDiagram } from "./sequence-diagram"
import type { SequenceLayoutOptions } from "./types"

export interface JourneySlide {
  id: string
  title?: string
  caption?: string
  chart: string
  messageCaptions?: string[]
}

function captionsFromChart(chart: string): string[] {
  const model = parseSequenceDiagram(chart)
  return model.events
    .filter((event) => event.kind === "message" || event.kind === "note")
    .map((event) => event.explanation ?? "")
}

export interface JourneyPlayerProps extends Omit<SequenceLayoutOptions, "animateIn"> {
  slides: JourneySlide[]
  activeSlideId?: string
  onSlideChange?: (id: string) => void
  className?: string
  /** Height of the diagram viewport. Defaults to 420px. */
  height?: number
  /** Fixed dwell time per slide during autoplay. */
  autoPlayIntervalMs?: number
  /** Begin playback automatically. Defaults to true. */
  autoPlay?: boolean
  /** Restart after the final step. Defaults to true. */
  loop?: boolean
  /** Called when the final step finishes. */
  onComplete?: () => void
}

const MIN_DWELL_MS = 2600
const MAX_DWELL_MS = 7000
const MS_PER_CAPTION_CHAR = 30

function dwellTimeFor(slide: JourneySlide, speed: number, override?: number) {
  const base =
    override ??
    (slide.caption
      ? Math.min(
          MAX_DWELL_MS,
          Math.max(MIN_DWELL_MS, MIN_DWELL_MS + slide.caption.length * MS_PER_CAPTION_CHAR),
        )
      : MIN_DWELL_MS)
  return base * speed
}

/**
 * Plays a sequence of diagrams as a focused journey. The player intentionally
 * owns only navigation/playback controls; editing, themes, source format, and
 * other authoring UI belong to the parent experience.
 */
export function JourneyPlayer({
  slides,
  activeSlideId,
  onSlideChange,
  className,
  height = 420,
  columnGap,
  messageGap,
  showBottomActors,
  autoPlayIntervalMs,
  autoPlay = true,
  loop = true,
  onComplete,
  speed = 1,
}: JourneyPlayerProps) {
  const [prefersReducedMotion] = useState(() => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches)
  const [internalIndex, setInternalIndex] = useState(0)
  const controlledIndex = activeSlideId == null ? -1 : slides.findIndex((slide) => slide.id === activeSlideId)
  const index = controlledIndex >= 0 ? controlledIndex : internalIndex
  const setIndex = (next: number | ((current: number) => number)) => {
    const value = typeof next === "function" ? next(index) : next
    const bounded = Math.max(0, Math.min(slides.length - 1, value))
    if (activeSlideId == null) setInternalIndex(bounded)
    if (slides[bounded]?.id && bounded !== index) onSlideChange?.(slides[bounded].id)
  }
  const [playing, setPlaying] = useState(autoPlay && !prefersReducedMotion)
  const [looping, setLooping] = useState(loop)
  const [inspecting, setInspecting] = useState(false)
  const [captionIndex, setCaptionIndex] = useState(-1)
  const [copied, setCopied] = useState(false)

  const slide = slides[index]
  const atStart = index === 0
  const atEnd = index === slides.length - 1
  const canPlay = slides.length > 1

  const schedule = useMemo(
    () => (slide ? getStepSchedule(parseSequenceDiagram(slide.chart), speed) : { delays: [] }),
    [slide, speed],
  )

  const captions = useMemo(
    () => (slide ? slide.messageCaptions ?? captionsFromChart(slide.chart) : []),
    [slide],
  )
  const hasCaptions = captions.some((caption) => caption.length > 0)
  // Reserve adequate vertical space for the full sequence, rather than
  // squeezing long journeys into a fixed 420px viewport.
  const diagramHeight = useMemo(() => {
    if (!slide) return height
    const graph = buildSequenceGraph(parseSequenceDiagram(slide.chart), {
      columnGap,
      messageGap,
      showBottomActors,
    })
    return Math.max(height, Math.min(760, Math.ceil(graph.height * 0.95)))
  }, [slide, height, columnGap, messageGap, showBottomActors])

  function goTo(next: number) {
    setPlaying(false)
    setIndex(Math.max(0, Math.min(slides.length - 1, next)))
  }

  function togglePlay() {
    if (!canPlay) return
    if (playing) {
      setPlaying(false)
      return
    }
    if (atEnd && !looping) setIndex(0)
    setPlaying(true)
  }

  async function handleCopy() {
    if (!slide) return
    try {
      await navigator.clipboard.writeText(slide.chart.trim())
      setCopied(true)
      window.setTimeout(() => setCopied(false), 1600)
    } catch {
      // Clipboard API can be unavailable in insecure contexts.
    }
  }

  useEffect(() => {
    setInternalIndex(0)
    setPlaying(autoPlay && !prefersReducedMotion)
    setLooping(loop)
  }, [slides, autoPlay, loop]) // eslint-disable-line react-hooks/exhaustive-deps

  useEffect(() => {
    if (!playing || !slide || inspecting) return

    const scheduleFloor =
      schedule.delays.length > 0 ? schedule.delays[schedule.delays.length - 1] + 1200 * speed : 0
    const dwell = Math.max(dwellTimeFor(slide, speed, autoPlayIntervalMs), scheduleFloor)

    if (atEnd) {
      const id = window.setTimeout(() => {
        onComplete?.()
        if (looping) setIndex(0)
        else setPlaying(false)
      }, dwell)
      return () => window.clearTimeout(id)
    }

    const id = window.setTimeout(() => setIndex((current) => current + 1), dwell)
    return () => window.clearTimeout(id)
  }, [playing, looping, atEnd, slide, speed, autoPlayIntervalMs, schedule, inspecting, onComplete])

  useEffect(() => {
    setCaptionIndex(-1)
    if (!hasCaptions) return
    const count = Math.min(captions.length, schedule.delays.length)
    const timers = Array.from({ length: count }, (_, caption) =>
      window.setTimeout(() => setCaptionIndex(caption), schedule.delays[caption]),
    )
    return () => timers.forEach(window.clearTimeout)
  }, [slide, captions, hasCaptions, schedule])

  useEffect(() => {
    setCopied(false)
  }, [slide])

  function handleKeyDown(event: React.KeyboardEvent) {
    if (event.key === "ArrowRight") {
      event.preventDefault()
      goTo(index + 1)
    } else if (event.key === "ArrowLeft") {
      event.preventDefault()
      goTo(index - 1)
    } else if (event.key === " " || event.key === "Spacebar") {
      event.preventDefault()
      togglePlay()
    }
  }

  if (!slide) return null

  return (
    <div
      role="group"
      aria-roledescription="carousel"
      aria-label={slide.title ?? "Diagram journey"}
      tabIndex={0}
      onKeyDown={handleKeyDown}
      onMouseEnter={() => setInspecting(true)}
      onMouseLeave={() => setInspecting(false)}
      onFocusCapture={() => setInspecting(true)}
      onBlurCapture={(event) => { if (!event.currentTarget.contains(event.relatedTarget)) setInspecting(false) }}
      className={cn("flex flex-col gap-4 outline-none", className)}
    >
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex min-w-0 flex-col gap-0.5">
          {slide.title ? (
            <span className="truncate text-sm font-medium text-foreground">{slide.title}</span>
          ) : null}
          <span className="text-xs text-muted-foreground">
            Step {index + 1} of {slides.length}
          </span>
        </div>

        <div className="flex items-center gap-3">
          <div className="flex items-center gap-1.5" role="tablist" aria-label="Journey steps">
            {slides.map((item, itemIndex) => (
              <button
                key={item.id}
                type="button"
                role="tab"
                aria-selected={itemIndex === index}
                aria-label={`Go to step ${itemIndex + 1}${item.title ? `: ${item.title}` : ""}`}
                onClick={() => goTo(itemIndex)}
                className={cn(
                  "size-1.5 transition-colors",
                  itemIndex === index ? "bg-primary" : "bg-border hover:bg-muted-foreground",
                )}
              />
            ))}
          </div>

          <div className="flex border border-border">
            <button
              type="button"
              aria-label="Previous step"
              disabled={atStart}
              onClick={() => goTo(index - 1)}
              className="flex items-center justify-center border-r border-border p-1.5 text-muted-foreground transition-colors hover:text-foreground disabled:pointer-events-none disabled:opacity-30"
            >
              <ChevronLeft className="size-4" aria-hidden />
            </button>
            <button
              type="button"
              aria-label="Next step"
              disabled={atEnd}
              onClick={() => goTo(index + 1)}
              className="flex items-center justify-center border-r border-border p-1.5 text-muted-foreground transition-colors hover:text-foreground disabled:pointer-events-none disabled:opacity-30"
            >
              <ChevronRight className="size-4" aria-hidden />
            </button>
            {canPlay ? (
              <button
                type="button"
                aria-label={playing ? "Pause journey" : "Play journey"}
                aria-pressed={playing}
                onClick={togglePlay}
                className="flex items-center justify-center border-r border-border p-1.5 text-muted-foreground transition-colors hover:text-foreground"
              >
                {playing ? <Pause className="size-4" aria-hidden /> : <Play className="size-4" aria-hidden />}
              </button>
            ) : null}
            <button
              type="button"
              aria-label={looping ? "Disable autoplay loop" : "Enable autoplay loop"}
              aria-pressed={looping}
              onClick={() => setLooping((value) => !value)}
              className={cn(
                "flex items-center justify-center border-r border-border p-1.5 transition-colors",
                looping ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground",
              )}
            >
              <Repeat2 className="size-4" aria-hidden />
            </button>
            <button
              type="button"
              aria-label={copied ? "Copied current diagram" : "Copy current diagram"}
              onClick={handleCopy}
              className="flex items-center justify-center p-1.5 text-muted-foreground transition-colors hover:text-foreground"
            >
              {copied ? <Check className="size-4" aria-hidden /> : <Copy className="size-4" aria-hidden />}
            </button>
          </div>
        </div>
      </div>

      <div className="relative overflow-hidden border border-border bg-card" style={{ height: diagramHeight }}>
        <SequenceDiagram
          key={slide.id}
          chart={slide.chart}
          className="size-full"
          animateIn
          speed={speed}
          columnGap={columnGap}
          messageGap={messageGap}
          showBottomActors={showBottomActors}
        />
      </div>

      {hasCaptions ? (
        <div
          key={`${slide.id}-live-caption`}
          data-journey-live-caption
          aria-live="polite"
          className="flex min-h-10 items-center border border-border bg-card px-3 py-2 text-card-foreground"
        >
          {captionIndex >= 0 && captions[captionIndex] ? (
            <p key={captionIndex} className="seq-enter text-sm leading-relaxed text-inherit">
              <span className="mr-2 text-xs font-medium tabular-nums text-seq-accent">
                {captionIndex + 1}/{captions.length}
              </span>
              {captions[captionIndex]}
            </p>
          ) : (
            <p className="text-sm text-inherit opacity-70">Watch the diagram to follow along…</p>
          )}
        </div>
      ) : null}

      {slide.caption ? (
        <p
          key={slide.id}
          className="seq-enter border-t border-border pt-3 text-sm leading-relaxed text-foreground/70"
        >
          {slide.caption}
        </p>
      ) : null}
    </div>
  )
}

