export function createStandaloneJourneyHtml(slides: JourneySlide[], options: JourneyHtmlOptions = {}) {
  if (!Array.isArray(slides) || slides.length < 1 || slides.length > 100) throw new RangeError("Expected 1–100 journey slides")
  for (const slide of slides) {
    if (!slide || typeof slide.chart !== "string" || slide.chart.length > 25000 || slide.chart.split(/\r?\n/).length > 500) throw new RangeError("Invalid or oversized journey chart")
  }
  const title = options.title ?? slides[0]?.title ?? "Sequence Flow journey"
  const payload = safeJson({ title, slides })
  const dark = options.theme === "dark"
  return `<!doctype html>
<html lang="en" data-theme="${dark ? "dark" : "light"}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title.replace(/[<>&"]/g, "")}</title>
<style>:root{color-scheme:light;--bg:#f7f7f5;--fg:#141414;--card:#fff;--line:#d8d8d2;--muted:#6b6b66;--accent:#b33a22;--accent-fg:#fff;--grp:rgba(179,58,34,.05)}html[data-theme=dark]{color-scheme:dark;--bg:#171717;--fg:#f1f1ee;--card:#1f1f1f;--line:#3a3a38;--muted:#a5a5a0;--accent:#ed7459;--accent-fg:#1b1b1b;--grp:rgba(237,116,89,.08)}
${STYLE}</style></head>
<body><main class="shell"><div class="top"><span class="eyebrow">Sequence Flow / exported journey</span><button class="action" id="theme">Theme</button></div><section class="frame" aria-label="Journey player"><div class="copy"><span class="eyebrow" id="count"></span><h1 id="title"></h1><p class="caption" id="caption"></p></div><div class="stage-wrap"><div class="stage" id="stage"><div class="canvas" id="canvas"></div><div class="tip" id="tip"></div><div class="zoom" aria-label="Canvas controls"><button id="zoomIn" title="Zoom in">+</button><button id="zoomOut" title="Zoom out">&minus;</button><button id="fit" title="Fit view">Fit</button></div><span class="mark">Sequence Flow</span></div></div><div class="controls"><div class="steps" id="steps"></div><div class="btns"><button class="action" id="prev">Prev</button><button class="action" id="play">Play</button><button class="action" id="next">Next</button></div></div></section><p class="made">Built in Montréal by Canadian AI</p><p class="sr" aria-live="polite" id="live"></p></main>
<script type="application/json" id="journey-data">${payload}</script><script>${RUNTIME}</script></body></html>`
}

export function downloadJourneyHtml(slides: JourneySlide[], options: JourneyHtmlOptions = {}) {
  const blob = new Blob([createStandaloneJourneyHtml(slides, options)], { type: "text/html;charset=utf-8" })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement("a")
  anchor.href = url
  anchor.download = sanitizeJourneyFilename(options.title ?? slides[0]?.title)
  anchor.click()
  URL.revokeObjectURL(url)
}

import type { JourneySlide } from "./journey-player"

const styles = `:host{display:block;color:#111;font:14px/1.5 system-ui,sans-serif}.frame{border:1px solid #999;background:#fff}.head,.foot{padding:16px}.head{border-bottom:1px solid #999}.foot{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid #999}.title{margin:0 0 4px;font:700 22px Georgia,serif}.caption{margin:0;color:#666}.chart{margin:0;min-height:240px;overflow:auto;padding:20px;white-space:pre;font:12px/1.7 ui-monospace,monospace}button{border:1px solid #999;background:transparent;padding:7px 10px;color:inherit;cursor:pointer}:host([theme=dark]){color:#eee}:host([theme=dark]) .frame{background:#222}`

const HTMLElementBase = (typeof HTMLElement === "undefined" ? class {} : HTMLElement) as typeof HTMLElement

export class SequenceFlowJourneyElement extends HTMLElementBase {
  static observedAttributes = ["slides", "theme"]
  private index = 0
  private slides: JourneySlide[] = []
  /** Select a slide externally by id or zero-based index. */
  selectSlide(target: string | number) {
    const index = typeof target === "number" ? target : this.slides.findIndex((slide) => slide.id === target)
    if (!Number.isInteger(index) || index < 0 || index >= this.slides.length) return false
    this.index = index
    this.render()
    this.dispatchEvent(new CustomEvent("sequence-flow:slide-change", { detail: { index, id: this.slides[index].id }, bubbles: true, composed: true }))
    return true
  }

  connectedCallback() { this.load(); this.render() }
  attributeChangedCallback() { if (this.isConnected) { this.load(); this.render() } }

  private load() {
    const source = this.getAttribute("slides") || this.querySelector('script[type="application/json"]')?.textContent || "[]"
    try { const value = JSON.parse(source); this.slides = Array.isArray(value) ? value : value.slides ?? [] } catch { this.slides = [] }
    this.index = Math.min(this.index, Math.max(0, this.slides.length - 1))
  }

  private render() {
    const root = this.shadowRoot ?? this.attachShadow({ mode: "open" })
    root.replaceChildren()
    const style = document.createElement("style"); style.textContent = styles
    const frame = document.createElement("section"); frame.className = "frame"; frame.setAttribute("aria-label", "Sequence Flow journey")
    const slide = this.slides[this.index]
    if (!slide) { frame.textContent = "Add journey slides with the slides attribute or a nested application/json script."; root.append(style, frame); return }
    const head=document.createElement("header");head.className="head"
    const title=document.createElement("h2");title.className="title";title.textContent=slide.title||`Step ${this.index+1}`
    const caption=document.createElement("p");caption.className="caption";caption.textContent=slide.caption||""
    const chart=document.createElement("pre");chart.className="chart";chart.textContent=slide.chart.trim()
    const foot=document.createElement("footer");foot.className="foot"
    const count=document.createElement("span");count.textContent=`Step ${this.index+1} of ${this.slides.length}`
    const controls=document.createElement("div")
    const prev=document.createElement("button");prev.textContent="Previous";prev.disabled=this.index===0;prev.onclick=()=>{this.selectSlide(this.index-1)}
    const next=document.createElement("button");next.textContent="Next";next.disabled=this.index===this.slides.length-1;next.onclick=()=>{this.selectSlide(this.index+1)}
    controls.append(prev,next);head.append(title,caption);foot.append(count,controls);frame.append(head,chart,foot);root.append(style,frame)
  }
}

export function registerSequenceFlowJourney(tagName = "sequence-flow-journey") {
  if (typeof customElements !== "undefined" && !customElements.get(tagName)) customElements.define(tagName, SequenceFlowJourneyElement)
}
